function productDefaults(){defaults({owners:{},rewards:[{id:'r1',name:'决定一次家庭桌游',cost:15},{id:'r2',name:'选择周末家庭活动',cost:25}],redemptions:[]})}
function productRender(){const earned=state.weeks.reduce((a,x)=>a+x.points,0),used=p.redemptions.reduce((a,x)=>a+x.cost,0),balance=earned-used;put(`<div class="stats">${stat('已结算积分',earned)}${stat('已兑换积分',used)}${stat('可兑换积分',balance)}</div><div class="grid"><div>${box('奖励兑换站',rows(p.rewards,r=>`<div class="item"><div><strong>${esc(r.name)}</strong><p>${r.cost} 积分</p></div><button data-redeem="${r.id}" ${balance<r.cost?'disabled':''}>兑换</button></div>`)+note('只有已完成周结算的积分可兑换，未结算任务可继续修改。'))}${box('兑换记录',rows(p.redemptions.slice().reverse(),r=>`<div class="item"><div>${esc(r.name)}<p>${r.date} · ${r.cost} 积分</p></div><button data-cancel="${r.id}" class="small">撤销兑换</button></div>`))}</div><div>${box('任务分工与积分规则',`<form id="assign" class="stack"><label>任务<select name="id">${state.tasks.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>${field('负责成员代号','owner','text','','required maxlength="20"')}${field('本任务积分','points','number',5,'required min="1" max="100"')}<button>保存任务分工</button></form>${state.tasks.map(x=>`<p>${esc(x.name)}：${esc(p.owners[x.id]||'尚未分工')} / ${x.points} 分</p>`).join('')}`)}${box('共同设计奖励',`<form id="reward" class="stack">${field('奖励内容','name','text','','required maxlength="60"')}${field('所需积分','cost','number',20,'required min="1" max="10000"')}<button>新增奖励</button></form>`)}</div></div>`);deleteButtons('redeem',id=>{const r=p.rewards.find(x=>x.id===id);if(balance<r.cost)return; p.redemptions.push({...r,id:uid(),date:today()});commit()});deleteButtons('cancel',id=>{p.redemptions=p.redemptions.filter(x=>x.id!==id);commit()});form('assign',v=>{const t=state.tasks.find(x=>x.id===v.id);if(!t)return; t.points=+v.points;p.owners[t.id]=v.owner;commit()});form('reward',v=>{p.rewards.push({...v,id:uid(),cost:+v.cost});commit()})}
